/* ===== Swing trading A: foundations & reading charts ===== */

STT('st-what', { name: 'What swing trading is', cat: 'stfound',
  blurb: `Swing trading means holding a position for a few days to a few weeks to capture one "swing" in price — a move inside a larger trend. It sits between day trading (in and out the same day) and investing (months to years). This page sets honest expectations before any technique.`,
  facts: [['Hold time', 'days to weeks'], ['Goal', 'catch one price swing'], ['Screen time', 'minutes a day, not all day'], ['Reality', 'risk of loss is real']],
  cheat: [['Scalping', 'seconds–minutes; dozens of trades a day'], ['Day trading', 'minutes–hours; closed by end of day'], ['Swing trading', 'days–weeks; a handful of trades a month'], ['Position trading', 'weeks–months; follows the big trend'], ['Investing', 'months–years; owns the business, ignores noise'], ['Edge', 'a repeatable reason your wins beat your losses over time'], ['R (risk unit)', 'the dollars you risk per trade; targets measured in multiples of R'], ['Win rate', '% of trades that profit — means little without R:R'], ['Expectancy', 'average profit per trade over many trades'], ['Drawdown', 'the drop from a peak in your account — expect them']],
  sections: [
    [RISK, PP(`Everything below is a skill you build slowly. Treat early trades as tuition.`)],
    ['Where swing trading sits', TBL(['Style', 'Hold time', 'Trades', 'Suits you if…'], [['Scalping', 'seconds–minutes', 'very many', 'You want full-time, fast, high-stress work'], ['Day trading', 'minutes–hours', 'several/day', 'You can watch screens all day and close flat each night'], ['Swing trading', 'days–weeks', 'a few/month', 'You have a job/life and check charts once or twice a day'], ['Investing', 'months–years', 'rare', 'You want to own assets long-term and ignore noise']]) + PP(`Swing trading is popular precisely because it does not demand all-day screen time: you plan on the daily chart, set your orders, and let the trade work.`)],
    ['What a "swing" looks like', FIG(chart({ w: 560, h: 240, candles: trend(28, 20, 0.16, 1.0, 5), vzones: [{ i1: 9, i2: 16, cls: 'stc-z-buy', label: 'one swing you try to catch' }] }), 'Price moves in waves even while trending. A swing trade aims to capture one up-wave (or down-wave), not the whole move.')],
    ['Honest expectations', UL([`Most beginners lose money at first. The edge is small and takes time to build; survival (not getting rich) is the first goal.`, `You will have losing streaks. A good trader with a 50% win rate still loses 5–6 in a row sometimes — that is normal variance, not failure.`, `Profit comes from <b>risk management and consistency</b>, not from predicting every move. You will be wrong often and still make money if winners are bigger than losers.`, `Start on a <b>demo/paper account</b>, then trade tiny real size. Scale up only after months of consistent results.`])],
    ['The two things that actually matter', PP(`Beginners obsess over entries ("when to buy"). Professionals obsess over <b>risk per trade</b> and <b>reward-to-risk</b>. If you risk 1R to make 2R and win just 40% of the time, you are profitable. Get those two right and mediocre entries still work; get them wrong and perfect entries still blow up the account. This is covered in depth in the Risk units — read them early, not last.`)]
  ],
  edge: [`"Get rich quick" is how accounts get emptied — swing trading is a slow skill, and leverage makes losses fast.`, `Overtrading (taking trades out of boredom) is the most common way beginners bleed money; a few good setups beat many mediocre ones.`, `A high win rate with tiny winners and huge losers still loses money — reward-to-risk matters more than being "right".`, `Backtested or demo success does not transfer until you can handle real money emotionally; start tiny.`, `Never risk rent, savings, or borrowed money; trade only truly spare capital.`],
  faq: [['How much money do I need to start?', PP(`Enough to practise risk management with real (small) stakes once you are past demo — but the amount matters less than the <b>percentage</b> you risk per trade. Risking 1% of a $500 account teaches the same discipline as 1% of $50,000. Start small deliberately: the goal early on is to learn without meaningful financial pain. This is general education, not a recommendation of any amount.`)],
    ['Can I do this with a full-time job?', PP(`Yes — that is swing trading’s main appeal. You analyse on the daily chart in the evening, place <b>limit and stop orders</b> so you do not need to watch intraday, and manage positions in a few minutes a day. It demands discipline more than hours.`)],
    ['Is swing trading gambling?', PP(`It can be, if done without an edge, risk limits, or a plan — then it is just betting. Done properly it is a <b>probabilistic business</b>: you take setups with positive expectancy, size risk so no single trade hurts you, and let the numbers play out over many trades. The discipline is what separates it from gambling.`)]],
  qs: [SQ('What is the typical holding period for a swing trade?', ['Seconds to minutes', 'A few days to a few weeks', 'Months to years', 'Exactly one day'], 1, 'Swing trades capture a multi-day price swing, between day trading and investing.'),
    SQ('What matters most for long-term profitability?', ['Predicting every move correctly', 'A very high win rate', 'Risk management and reward-to-risk consistency', 'Trading as often as possible'], 2, 'Controlling risk per trade and keeping winners larger than losers is what makes the math work.')]
});
DP('st-what', {
  fu: [['What is “expectancy” and why does it beat win rate?', 'Expectancy = (win% × average win) − (loss% × average loss): the average profit per trade over many trades. A 40% win rate with 3R winners and 1R losers has positive expectancy (0.4×3 − 0.6×1 = +0.6R per trade); a 70% win rate with 1R winners and 3R losers is negative. Win rate alone tells you nothing.'],
    ['Why start on a demo account?', 'To learn the platform, test a strategy, and build routine without risking money — and to see your own emotional reactions. Demo cannot fully replicate the fear/greed of real money, so follow it with very small real trades before scaling.'],
    ['What is a realistic return?', 'There is no guaranteed number, and anyone promising one is a red flag. Professionals think in terms of risk-adjusted consistency and surviving drawdowns, not a fixed monthly percentage. Many beginners are net negative in year one; the aim early is to not blow up while you learn.']],
  deep: [['Mindset', 'Trading is a game of probabilities and risk, not prediction. You can be wrong half the time and still profit if your winners are larger than your losers and you never let one trade ruin you.'],
    ['Failure mode', 'Blowing up: over-leveraging, no stop loss, revenge-trading after a loss, or risking too much per trade. One or two of these ends most accounts in the first year.'],
    ['In real markets', 'Even top traders have losing months and deep drawdowns; their edge shows over hundreds of trades, not any single one. Consistency and capital preservation are the whole game.']],
  src: ['Investopedia: Swing Trading', 'https://www.investopedia.com/terms/s/swingtrading.asp'] });

STT('st-markets', { name: 'Markets & instruments: what to trade', cat: 'stfound',
  blurb: `You can swing trade stocks, ETFs, forex, crypto, futures and more. They share the same chart-reading skills but differ in hours, leverage, costs and risk. This page helps a beginner choose a sensible starting market.`,
  facts: [['Beginner-friendly', 'liquid large-cap stocks & major ETFs'], ['Open 24/5', 'forex'], ['Open 24/7', 'crypto (very volatile)'], ['Key traits', 'liquidity + volatility + cost']],
  cheat: [['Stocks', 'Shares of companies; day session hours; great for swing trading'], ['ETFs', 'Baskets (e.g. an index); diversified, smoother, beginner-friendly'], ['Forex', 'Currency pairs; 24/5; high leverage available (and dangerous)'], ['Crypto', '24/7; very volatile; smaller caps can be manipulated'], ['Futures', 'Leveraged contracts on indices/commodities; pros'], ['Options', 'Leverage + time decay; advanced; easy to lose fast'], ['Liquidity', 'How easily you can get in/out at a fair price'], ['Volatility', 'How much it moves — you need some, not chaos'], ['Spread', 'Gap between buy and sell price — a cost'], ['Market cap', 'Big = more stable; small = wilder, thinner']],
  sections: [
    ['The main markets compared', TBL(['Market', 'Hours', 'Leverage', 'Notes for swing traders'], [['Large-cap stocks', 'Exchange hours', 'Low/none (cash)', 'Clear trends, deep liquidity, reliable patterns — a great place to learn'], ['ETFs (index/sector)', 'Exchange hours', 'Low/none', 'Diversified and less jumpy than single stocks; fewer surprises'], ['Forex (majors)', '24/5', 'High', 'Deep liquidity, trends well; high leverage is a trap for beginners'], ['Crypto (majors)', '24/7', 'High on derivatives', 'Huge moves and opportunity, but volatile, news-driven, and never closes'], ['Futures', 'Nearly 24/5', 'High', 'Efficient index/commodity exposure; leverage demands experience'], ['Options', 'Exchange hours', 'Built-in', 'Powerful but time decay and complexity make them advanced']]) + PP(`All of these are read with the <b>same charts and patterns</b>. Pick one market and one or two instruments to start; do not scatter across all of them.`)],
    ['What makes an instrument good to swing trade', UL([`<b>Liquidity:</b> enough volume that your orders fill near the price you want, with a tight spread. Avoid thin, illiquid names.`, `<b>Volatility (the right amount):</b> it must move enough to be worth trading, but not be so wild that stops get hit randomly. Steady trending names beat chaotic ones.`, `<b>Clean price action:</b> respects support/resistance and trends, rather than whipsawing on every headline.`, `<b>Reasonable cost:</b> low spreads/commissions; costs quietly erode an edge.`])],
    ['A sensible beginner path', OL([`Start with <b>large-cap stocks or major ETFs</b> in your own market: liquid, well-behaved, and you can trade without leverage.`, `Learn to read one chart well before adding instruments.`, `Only consider forex, crypto or futures once you understand leverage and risk — and even then, keep leverage tiny.`, `Avoid penny stocks, micro-cap crypto, and exotic products early: they are thin, manipulated, and punish beginners.`])],
    ['Why leverage deserves fear', PP(`Leverage lets you control a big position with little money. It multiplies gains <i>and</i> losses: 10× leverage means a 10% move against you wipes out your capital. Many beginners are drawn to forex and crypto derivatives for the leverage and are liquidated within weeks. Treat leverage as an accelerant to be used sparingly and late, if at all.`)]
  ],
  edge: [`High leverage (common in forex/crypto) can liquidate an account on a small move — it is the fastest way beginners lose everything.`, `Thin, low-volume instruments have wide spreads and gaps, and stops can slip badly; stick to liquid names.`, `Crypto never closes, so it can gap hard while you sleep — size positions with that in mind.`, `Single stocks carry company-specific risk (earnings, news gaps); ETFs spread that risk.`, `Trading many markets at once splits your focus and your capital — master one first.`],
  faq: [['Stocks or forex or crypto for a beginner?', PP(`For most beginners, <b>liquid large-cap stocks or broad ETFs</b> are the gentlest classroom: regular hours, no required leverage, clean trends, and abundant learning material. Forex and crypto are tradable with the same skills but add leverage and (for crypto) 24/7 volatility that punish inexperience. Learn on the calmer market, then branch out deliberately.`)],
    ['Do I need a lot of volatility to make money?', PP(`You need <i>enough</i> movement to produce swings worth trading, but more volatility is not automatically better — it also means wider stops and more random whipsaws. The sweet spot is an instrument that trends and respects levels. Steady, liquid movers are easier to trade than chaotic ones.`)],
    ['Are ETFs really good for swing trading?', PP(`Yes, especially early. A broad or sector ETF trends cleanly, is highly liquid, and avoids single-company surprises like a bad earnings report gapping the price overnight. You give up some explosive moves for much smoother, more forgiving behaviour — a good trade-off while learning.`)]],
  qs: [SQ('Which market is generally the most beginner-friendly for swing trading?', ['Micro-cap crypto', 'Liquid large-cap stocks and major ETFs', 'Exotic options', 'Penny stocks'], 1, 'Liquid, well-behaved, no required leverage — the gentlest place to learn.'),
    SQ('Why is high leverage dangerous for beginners?', ['It reduces returns', 'It multiplies both gains and losses, so a small adverse move can wipe out capital', 'It is illegal', 'It slows down trades'], 1, 'Leverage amplifies losses as much as gains and can liquidate an account quickly.')]
});
DP('st-markets', {
  fu: [['What is the difference between a spread and a commission?', 'The spread is the gap between the bid (sell) and ask (buy) price — you cross it every round trip. A commission is a separate fee per trade. Both are costs; thin instruments have wide spreads that quietly eat small edges.'],
    ['Why can crypto be riskier than stocks beyond volatility?', 'Smaller-cap coins can be thinly traded and susceptible to manipulation, the market is 24/7 (so it gaps while you sleep), and custody/exchange risk adds a layer stocks do not have. Majors are safer than micro-caps but still volatile.'],
    ['Does the same technical analysis work across markets?', 'Largely yes — support/resistance, trends, candlesticks and indicators are price-and-psychology based and apply to any liquid market. The differences are in hours, leverage, costs and how news-driven each is, not in how you read the chart.']],
  deep: [['Technique', 'Build a small watchlist of liquid instruments you understand, rather than hopping markets. Depth on a few names beats shallow coverage of many.'],
    ['Failure mode', 'Chasing the most volatile thing of the moment (a hot small-cap or meme coin) with leverage — thin liquidity plus big size is how accounts vanish.'],
    ['In real markets', 'Professionals specialise: an equity swing trader may trade the same 20–50 liquid names for years, learning their personalities, rather than trading everything.']],
  src: ['Investopedia: What Is a Financial Market?', 'https://www.investopedia.com/terms/m/market.asp'] });

STT('st-mechanics', { name: 'How orders work: bid/ask, order types & going short', cat: 'stfound',
  blurb: `Before reading charts, understand the plumbing: how prices are quoted, the order types you will use, and what it means to go long or short. Getting orders right is how you enter and exit at the prices you intend — and how your stop loss actually protects you.`,
  facts: [['Quote', 'bid (sell) / ask (buy)'], ['Spread', 'ask − bid, a cost'], ['Enter at a price', 'limit order'], ['Protect a trade', 'stop order']],
  cheat: [['Bid', 'Highest price buyers will pay (you sell here)'], ['Ask / offer', 'Lowest price sellers will accept (you buy here)'], ['Spread', 'Ask − bid; crossing it is a cost'], ['Market order', 'Fill now at best available price (fast, but slippage)'], ['Limit order', 'Fill only at your price or better (control, may not fill)'], ['Stop (stop-market)', 'Becomes a market order when price hits your stop level'], ['Stop-limit', 'Becomes a limit order at the stop — may not fill in a fast move'], ['Long', 'Buy first, profit if price rises'], ['Short', 'Sell first (borrowed), profit if price falls'], ['Slippage', 'Filling worse than expected in fast/thin markets']],
  sections: [
    ['Bid, ask and the spread', PP(`Every market shows two prices: the <b>bid</b> (what buyers offer) and the <b>ask</b> (what sellers want). You buy at the ask and sell at the bid, so the <b>spread</b> between them is an instant cost on every round trip. Liquid instruments have tiny spreads; thin ones have wide spreads that erode profits. When a chart shows "the price," it is usually the last trade or the mid-point.`)],
    ['The order types you will actually use', TBL(['Order', 'What it does', 'Use it to…'], [['Market', 'Fills immediately at the best current price', 'Get in/out now when fill certainty matters more than exact price'], ['Limit', 'Fills only at your specified price or better', 'Enter at a planned level (e.g. buy a pullback to support) without chasing'], ['Stop (stop-market)', 'Triggers a market order when price reaches the stop', 'Place your stop loss, or enter on a breakout above a level'], ['Stop-limit', 'Triggers a limit order at the stop price', 'Control fill price — but risk no fill if price gaps past it']]) + PP(`A typical swing trade uses a <b>limit order to enter</b>, a <b>stop order as the stop loss</b>, and a <b>limit order to take profit</b> — all placed in advance so you need not watch every tick.`)],
    ['Long vs short', FIG2(
      FIG(chart({ w: 270, h: 190, candles: trend(16, 20, 0.22, 0.8, 2), marks: [{ i: 2, p: 20.3, type: 'buy', label: 'buy' }] }), 'Long: buy low, aim to sell higher.'),
      FIG(chart({ w: 270, h: 190, candles: trend(16, 26, -0.22, 0.8, 4), marks: [{ i: 2, p: 25.7, type: 'sell', label: 'short' }] }), 'Short: sell high (borrowed), aim to buy back lower.')) +
      PP(`<b>Going long</b> is the familiar "buy low, sell high." <b>Going short</b> profits from falling prices: you borrow the asset, sell it, and buy it back cheaper. Shorting has special risks — losses are theoretically unlimited (price can keep rising), borrowing costs apply, and shares can be recalled — so beginners usually learn long trades first.`)],
    ['Slippage and gaps', PP(`A <b>market order</b> in a fast or thin market can fill worse than the last price you saw — that is <b>slippage</b>. Prices also <b>gap</b>: a stock can open far from its previous close after news, jumping over your stop so you exit worse than planned. This is why position sizing (risk units) matters: your actual loss can exceed the "distance to stop" on a bad gap.`)]
  ],
  edge: [`A market order can slip badly in fast or illiquid conditions — use limits when price precision matters.`, `A stop-<b>limit</b> can fail to fill if price gaps straight through it, leaving you in a losing trade with no exit — many traders use stop-<b>market</b> for protection.`, `Gaps can jump over your stop, so your real loss may exceed the planned distance; size positions assuming the occasional bad gap.`, `Shorting carries unlimited theoretical loss, borrow fees and recall risk — understand it fully before trying.`, `Wide spreads on thin instruments are a hidden, recurring cost — check the spread before trading.`],
  faq: [['Limit or market order to enter a swing trade?', PP(`Usually a <b>limit order</b> at a planned level (e.g. a pullback into support), so you control your entry price and reward-to-risk. Use a <b>market order</b> only when getting filled matters more than the exact price — for example exiting a trade that has clearly gone wrong. For breakouts, a <b>stop (stop-market)</b> order above the level enters you as it breaks.`)],
    ['Should my stop loss be a stop-market or stop-limit?', PP(`For protection, many traders prefer a <b>stop-market</b>: it guarantees you get out (just maybe at a slightly worse price in a fast move). A <b>stop-limit</b> controls the price but risks <i>not filling</i> if price gaps past the limit — leaving you still in a losing trade. The guaranteed exit is usually worth the possible slippage.`)],
    ['Is short selling something a beginner should do?', PP(`Generally learn <b>long</b> trades first. Shorting is a legitimate, important skill (markets fall faster than they rise), but it has extra risks: theoretically unlimited loss, borrow costs, and short squeezes. Once you are consistent on the long side and understand the mechanics, add shorting carefully with strict stops.`)]],
  qs: [SQ('You want to buy only if price pulls back to a specific support level, not above it. Which order?', ['Market order', 'Limit buy at that level', 'Stop-market above price', 'No order type does this'], 1, 'A limit order fills only at your price or better, ideal for a planned pullback entry.'),
    SQ('Why do many traders use a stop-market rather than a stop-limit for their stop loss?', ['It is cheaper', 'It guarantees an exit (even if slightly worse), while a stop-limit may not fill in a gap', 'It fills at a better price always', 'Stop-limits are illegal'], 1, 'Protection prioritises getting out; a stop-limit can leave you stuck if price jumps past it.')]
});
DP('st-mechanics', {
  fu: [['What is the order book / Level 2?', 'A live list of resting bids and asks at each price and their sizes. It shows liquidity and where big orders sit. Swing traders rarely need it, but it explains why liquid names fill cleanly and thin ones slip.'],
    ['How does margin differ from leverage?', 'Margin is borrowed money (or the collateral you post) to open a larger position; leverage is the ratio of position size to your own capital it produces. Trading on margin amplifies both returns and losses and can trigger a margin call forcing you to add funds or be liquidated.'],
    ['What is a short squeeze?', 'When a heavily-shorted asset rises, shorts rush to buy back to cut losses, pushing price up further and forcing more buying — a violent upward spiral. It is why uncapped short losses are dangerous and stops are essential when short.']],
  deep: [['Technique', 'Pre-place the whole trade: a limit entry, a stop-market stop loss, and a limit take-profit (a "bracket"/OCO order where available), so the plan executes without you watching every tick.'],
    ['Failure mode', 'Using market orders in thin conditions (big slippage), or stop-limits for protection that fail to fill on a gap — both turn a planned small loss into a larger one.'],
    ['In real markets', 'Overnight and weekend gaps are a core swing-trading risk: positions are held through closed sessions, so news can move price past your stop before you can act. Sizing assumes this.']],
  src: ['Investopedia: Order Types (Market, Limit, Stop)', 'https://www.investopedia.com/ask/answers/042215/whats-difference-between-market-order-and-limit-order.asp'] });

STT('st-plan', { name: 'The trading plan & journal', cat: 'stfound',
  blurb: `A trading plan turns random bets into a repeatable process; a journal turns experience into improvement. Without them you cannot tell skill from luck, or fix what is broken. This is the unglamorous habit that separates traders who last from those who don't.`,
  facts: [['Plan', 'your rules, written down'], ['Journal', 'every trade, reviewed'], ['Edge', 'why you expect to win over time'], ['First', 'paper trade the plan']],
  cheat: [['Setup', 'The specific conditions that trigger a trade'], ['Entry rule', 'Exactly where/why you get in'], ['Stop rule', 'Where the idea is wrong — exit'], ['Target rule', 'Where/how you take profit'], ['Risk per trade', 'Fixed % of account (e.g. 0.5–1%)'], ['Max exposure', 'Limit on open risk / correlated trades'], ['Routine', 'When you scan, review, journal'], ['Journal fields', 'Setup, screenshot, R:R, result in R, notes, emotion'], ['Review', 'Weekly: what worked, what to stop'], ['Edge', 'Positive expectancy proven over many trades']],
  sections: [
    ['What a trading plan contains', OL([`<b>Market & instruments:</b> what you trade and when.`, `<b>Setups:</b> the specific, repeatable conditions you wait for (e.g. "pullback to the 20-EMA in an uptrend with a bullish reversal candle").`, `<b>Entry, stop and target rules:</b> exactly where you get in, where you are wrong, and where you take profit — defined <i>before</i> the trade.`, `<b>Risk rules:</b> fixed risk per trade (a small % of the account), maximum simultaneous risk, and limits on correlated positions.`, `<b>Routine:</b> when you scan for setups, place orders, and review — and rules for when <i>not</i> to trade (news, tired, on tilt).`])],
    ['Why journaling is non-negotiable', PP(`A journal is how you learn. For every trade record the <b>setup, a chart screenshot, your planned entry/stop/target, the result in R, and how you felt</b>. Over 30–50 trades patterns emerge: maybe your breakout trades win but your counter-trend trades lose, or you cut winners too early. You cannot see these without data. The journal converts scattered experience into a measurable edge you can refine.`)],
    ['Measuring in R, not dollars', PP(`Record results in <b>R</b> (multiples of the amount you risked), not dollars. A trade where you risked $50 and made $100 is <b>+2R</b>. Thinking in R makes trades comparable regardless of size, keeps you focused on <b>reward-to-risk</b>, and lets you judge the strategy’s expectancy (average R per trade) honestly. Dollars tempt you to break rules when the number feels big or small.`)],
    ['The order of operations for a beginner', OL([`<b>Write the plan</b> — even a one-page version.`, `<b>Paper trade it</b> for weeks: follow the rules exactly, journal every trade.`, `<b>Review</b>: is the expectancy positive? Are you actually following the rules?`, `<b>Go live tiny</b>: real money, minimal size, same rules — to meet the emotions.`, `<b>Scale slowly</b> only after consistent, rule-following results. Most failures come from skipping straight to step 4 with big size.`])]
  ],
  edge: [`No written plan means every trade is improvised — you cannot improve what you do not define.`, `Not journaling means you repeat the same mistakes and cannot tell skill from luck.`, `Changing the plan after every loss ("strategy hopping") never lets any edge prove itself — give rules a meaningful sample (30+ trades).`, `Measuring in dollars instead of R tempts rule-breaking when the money feels big; think in R.`, `Trading while tired, angry, or "to make back" a loss (tilt) breaks plans — build a rule to step away.`],
  faq: [['Isn’t a trading plan overkill for small accounts?', PP(`No — it matters <i>most</i> when learning, regardless of size. The plan’s job is to make your behaviour consistent so you can measure whether your approach has an edge. On a small account the dollars are small but the habits you build (or fail to) are what carry forward when the account grows. Discipline is cheaper to learn small.`)],
    ['How many trades before I know if my strategy works?', PP(`Think in samples, not single trades. Any 5–10 trades are mostly noise; you want <b>30–50+</b> rule-following trades before judging expectancy, and more for lower-frequency setups. This is exactly why journaling matters: without recorded data you are guessing. Avoid abandoning a plan after a few losses — that is variance, not evidence.`)],
    ['What should I actually write for each trade?', PP(`At minimum: the date/instrument, the setup name, a chart screenshot marked with your entry/stop/target, the planned reward-to-risk, the outcome in R, and a sentence on your emotional state and whether you followed your rules. The emotional and rule-adherence notes are where the biggest improvements hide.`)]],
  qs: [SQ('Why measure trade results in R (risk multiples) instead of dollars?', ['Dollars are inaccurate', 'R makes trades comparable across sizes and keeps focus on reward-to-risk and expectancy', 'R is required by brokers', 'It hides losses'], 1, 'R normalises trades so you can judge the strategy, not the position size.'),
    SQ('What is the correct order for a beginner adopting a strategy?', ['Go live big immediately', 'Write plan → paper trade → review expectancy → go live tiny → scale slowly', 'Copy a stranger’s trades', 'Trade first, write rules later'], 1, 'Define, test, measure, then risk small real money before scaling.')]
});
DP('st-plan', {
  fu: [['What is “expectancy” in journal terms?', 'The average R your system returns per trade across your journal: sum of all trade results in R divided by the number of trades. Positive and stable over a large sample means a real edge; you can then size up carefully.'],
    ['How do I avoid strategy hopping?', 'Commit to trading one defined setup for a fixed sample (say 30–50 trades) before judging it, and only change one variable at a time. Switching after every loss guarantees you never learn whether anything works.'],
    ['What belongs in a weekly review?', 'Your trades grouped by setup and by rule-adherence: which setups made/lost R, where you broke rules, recurring emotional triggers, and one concrete change for next week. Small, data-driven adjustments beat wholesale rewrites.']],
  deep: [['Technique', 'Tag each journal entry (setup, long/short, followed-rules y/n, emotion). Filtering by tag reveals which setups and behaviours actually make money — often surprising.'],
    ['Failure mode', 'Trading without a plan or journal, then blaming the market. With no data you cannot separate a bad strategy from bad discipline from normal variance.'],
    ['In real practice', 'Nearly every durable trader keeps a journal and reviews it; it is the single highest-leverage habit and the one most beginners skip because it is unglamorous.']],
  src: ['Investopedia: Why You Need a Trading Plan', 'https://www.investopedia.com/articles/trading/04/042104.asp'] });

/* ---------------- Level 2: reading charts ---------------- */

STT('st-charttypes', { name: 'Chart types & timeframes', cat: 'stchart',
  blurb: `A chart turns price history into a picture you can read. Candlestick charts are the standard for swing trading because each bar shows the full battle between buyers and sellers. Timeframe choice decides what you see — and swing traders anchor on the daily chart.`,
  facts: [['Standard', 'candlestick chart'], ['Anchor timeframe', 'daily'], ['Context', 'weekly'], ['Entries', '4-hour / 1-hour']],
  cheat: [['Line chart', 'Connects closes; clean, hides detail'], ['Bar (OHLC)', 'Shows open/high/low/close as a bar'], ['Candlestick', 'Same OHLC, colour-coded body — easiest to read'], ['Timeframe', 'How much time each candle represents'], ['Weekly', 'Big-picture trend & major levels'], ['Daily', 'The swing trader’s primary chart'], ['4-hour / 1-hour', 'Fine-tuning entries'], ['Higher TF wins', 'Trade in the direction of the bigger timeframe'], ['Fewer candles, more signal', 'Higher TFs = less noise'], ['Multi-timeframe', 'Context (weekly) → setup (daily) → entry (4h)']],
  sections: [
    ['Three ways to draw the same price', FIG(chart({ w: 560, h: 230, candles: trend(26, 40, 0.14, 1.1, 8) }), 'A candlestick chart: each candle shows the open, high, low and close for its period. This is the standard for technical analysis because the body and wicks reveal who won the period.') +
      PP(`A <b>line chart</b> connects only closing prices — clean but it hides the range and the fight within each period. A <b>bar (OHLC) chart</b> shows all four prices as a tick-marked bar. A <b>candlestick chart</b> shows the same four prices but fills the body between open and close and colours it, making trend and momentum jump out. Swing traders use candlesticks.`)],
    ['Timeframes: what each candle represents', PP(`On a <b>daily</b> chart, each candle is one trading day; on a <b>weekly</b>, one week; on a <b>1-hour</b>, one hour. Higher timeframes compress more information into each candle, so they are <b>less noisy</b> and their signals carry more weight. Swing traders live on the <b>daily chart</b> — it matches the days-to-weeks holding period — and use the <b>weekly</b> for context and lower timeframes to refine entries.`)],
    ['Multi-timeframe alignment', TBL(['Timeframe', 'Role', 'Question it answers'], [['Weekly', 'Context', 'What is the big trend and where are the major levels?'], ['Daily', 'Setup', 'Is there a tradable setup in line with the big trend?'], ['4-hour / 1-hour', 'Entry', 'What is a precise, lower-risk entry into that setup?']]) + PP(`The rule: let the <b>higher timeframe set the direction</b>, and use the lower timeframe only to time the entry. A bullish daily setup against a falling weekly trend is a weaker trade.`)],
    ['Why higher timeframes are more reliable', PP(`Each candle on a higher timeframe is the sum of many lower-timeframe candles, so random noise averages out and only the meaningful move remains. A support level on the weekly chart is defended by far more participants than a level on the 5-minute chart, so it holds more often. Beginners who trade tiny timeframes drown in noise; anchoring on the daily is calmer and higher-probability.`)]
  ],
  edge: [`Trading very low timeframes (1–5 min) as a beginner means mostly noise, more costs, and emotional churn — anchor on the daily.`, `A great daily setup fighting the weekly trend is lower-probability; always check the higher timeframe first.`, `Switching timeframes to justify a trade you already want ("timeframe shopping") is a bias trap — decide your timeframes in advance.`, `Line charts hide the high/low range where stops and wicks matter — use candlesticks for decisions.`, `More indicators on more timeframes is not more insight; it is usually paralysis.`],
  faq: [['Which timeframe should a swing trader use?', PP(`The <b>daily chart is your home base</b> — it matches a holding period of days to weeks and filters out intraday noise. Use the <b>weekly</b> for the big-picture trend and major support/resistance, and drop to the <b>4-hour or 1-hour</b> only to fine-tune an entry. You do not need the 1-minute chart to swing trade.`)],
    ['Why candlesticks over line or bar charts?', PP(`Candlesticks show the same four prices as a bar chart but make them instantly readable: the coloured body shows whether buyers or sellers won the period and by how much, and the wicks show rejected extremes. This visual clarity is why candlestick patterns (a whole unit here) exist and why nearly all technical traders use them.`)],
    ['What is multi-timeframe analysis in one sentence?', PP(`Check the big trend on a higher timeframe, find your setup on your trading timeframe, and time the entry on a lower one — so you are always trading <i>with</i> the larger force, not against it.`)]],
  qs: [SQ('What is the primary chart timeframe for most swing traders?', ['1-minute', 'Daily', 'Monthly', 'Tick'], 1, 'The daily chart matches the days-to-weeks holding period and filters intraday noise.'),
    SQ('In multi-timeframe analysis, what sets the direction you should trade?', ['The lowest timeframe', 'The higher timeframe trend', 'Whichever agrees with your bias', 'The one with the most indicators'], 1, 'Let the higher timeframe set direction and use lower ones only to time entries.')]
});
DP('st-charttypes', {
  fu: [['What is Heikin-Ashi and should I use it?', 'Heikin-Ashi candles average price to smooth trends and make them visually clearer, at the cost of hiding the true open/close. Some traders use them for trend clarity, but for precise entries and candlestick patterns, standard candles are better. Learn standard candles first.'],
    ['Does the chart look different on log vs linear scale?', 'A logarithmic price scale shows equal percentage moves as equal distances — useful over long ranges or for assets that have multiplied many times (trendlines are more meaningful). Linear scale shows equal dollar moves. For most daily swing charts either works; log helps on big, long charts.'],
    ['How many candles should I see at once?', 'Enough to judge the trend and recent levels — commonly a few months of daily candles. Too few and you miss context; too many and recent structure gets tiny. Zoom so the current swing and the nearest major levels are both visible.']],
  deep: [['Technique', 'Top-down routine: open the weekly for trend and levels, mark them, drop to the daily for the setup, then (optionally) a 4h/1h for entry timing. Same levels drawn once, used across timeframes.'],
    ['Failure mode', 'Dropping to tiny timeframes for "more detail" and getting whipsawed by noise, or timeframe-shopping to confirm a pre-existing bias.'],
    ['In real charts', 'Major weekly support/resistance and round numbers tend to matter across all timeframes; levels from higher timeframes dominate lower ones.']],
  src: ['StockCharts ChartSchool: Chart Types', 'https://chartschool.stockcharts.com/table-of-contents/chart-analysis/chart-types'] });

STT('st-candle-anatomy', { name: 'Anatomy of a candlestick', cat: 'stchart',
  blurb: `Every candlestick encodes four prices — open, high, low, close — and the shape tells you who won that period and how decisively. Reading a single candle well is the atom of all candlestick analysis.`,
  facts: [['Encodes', 'open, high, low, close'], ['Body', 'open-to-close range'], ['Wicks', 'rejected high/low'], ['Colour', 'up (close>open) vs down']],
  cheat: [['Open', 'First traded price of the period'], ['Close', 'Last traded price (most important)'], ['High / Low', 'Extremes reached during the period'], ['Body', 'Rectangle between open and close'], ['Upper wick', 'High above the body — sellers pushed back'], ['Lower wick', 'Low below the body — buyers pushed back'], ['Bullish candle', 'Close above open (up colour)'], ['Bearish candle', 'Close below open (down colour)'], ['Long body', 'Strong, one-sided period'], ['Long wick', 'Rejection — price went there and was pushed back']],
  sections: [
    ['The four prices, drawn', FIG(chart({ w: 420, h: 250, candles: [[10, 12, 9.5, 11.5], [11.5, 12, 9, 10]], axis: false,
      notes: [{ i: 0.42, p: 12, text: 'High', anchor: 'end' }, { i: 0.42, p: 11.5, text: 'Close', anchor: 'end' }, { i: 0.42, p: 10, text: 'Open', anchor: 'end' }, { i: 0.42, p: 9.5, text: 'Low', anchor: 'end' },
        { i: 1.58, p: 12, text: 'High', anchor: 'start' }, { i: 1.58, p: 11.5, text: 'Open', anchor: 'start' }, { i: 1.58, p: 10, text: 'Close', anchor: 'start' }, { i: 1.58, p: 9, text: 'Low', anchor: 'start' }] }),
      'Left: a bullish candle (close above open). Right: a bearish candle (close below open). The body spans open→close; the thin wicks reach the high and low.')],
    ['What the shape tells you', TBL(['Shape', 'Meaning'], [['Long body, tiny wicks', 'Strong, decisive period — one side dominated'], ['Small body, long wicks', 'Indecision / rejection — a fight with no clear winner'], ['Long upper wick', 'Buyers pushed up but sellers rejected the highs (bearish hint)'], ['Long lower wick', 'Sellers pushed down but buyers rejected the lows (bullish hint)'], ['No/▼ tiny body (doji)', 'Open ≈ close: balance, often a turning hint in context']]) + PP(`The <b>close</b> matters most — it is where the period settled after all the fighting. A close near the high is strong; a close back near the open after a big range shows the move was rejected.`)],
    ['Colour and context', PP(`By convention an <b>up candle</b> (close above open) is drawn green/hollow and a <b>down candle</b> (close below open) red/filled — but colour just encodes close-vs-open. A single candle means little in isolation; its power comes from <b>where</b> it appears (at support, after a trend, on high volume). The pattern units build on this: they are just recognisable combinations of these shapes at meaningful locations.`)],
    ['Volume: the fuel behind the candle', PP(`Most charts show <b>volume</b> bars beneath price — how many shares/contracts traded in that period. A strong candle on <b>high volume</b> carries conviction; the same candle on low volume is suspect. Volume confirms (or doubts) what the candle appears to say, and it is a recurring theme in patterns and breakouts.`)]
  ],
  edge: [`One candle in isolation is noise — always read it in context (location, trend, volume).`, `Colour alone can mislead: a green candle that closed well off its highs (long upper wick) is weaker than it looks.`, `Different platforms colour candles differently; rely on body direction, not just the hue.`, `A long wick is rejection, but the timeframe matters — a big wick on the weekly is far more significant than on the 1-minute.`, `Don’t infer intra-candle order of events (you don’t know if the high or low came first) — only the four prices are known.`],
  faq: [['Why is the close considered the most important price?', PP(`Because it is where the period <i>settled</i> after all the buying and selling — the market’s final verdict for that candle. Opens can be noisy (gaps, overnight news), and highs/lows are extremes that may have been rejected. Many patterns and signals are defined by the close for this reason (e.g. "a close above resistance").`)],
    ['What does a long wick really mean?', PP(`That price travelled to that extreme and was <b>rejected</b> — pushed back before the close. A long <i>lower</i> wick means sellers drove price down but buyers reclaimed it (bullish hint, especially at support); a long <i>upper</i> wick means buyers pushed up but sellers slammed it back (bearish hint at resistance). Context and the next candle confirm it.`)],
    ['Do I need to watch volume on every candle?', PP(`You do not have to obsess over it, but volume is a valuable confirmation tool: strong moves and breakouts are more trustworthy on rising volume, and moves on fading volume are suspect. Make a habit of glancing at volume when a candle or pattern looks important — it often separates real signals from traps.`)]],
  qs: [SQ('On a candlestick, which price is generally considered the most significant?', ['The open', 'The high', 'The close', 'The midpoint'], 2, 'The close is where the period settled after all trading — the market’s verdict.'),
    SQ('A candle with a small body and a long lower wick at support suggests…', ['Sellers are in full control', 'Buyers rejected lower prices — a potential bullish hint', 'Nothing can be inferred', 'A guaranteed reversal'], 1, 'A long lower wick is rejection of lower prices; at support it hints buyers stepped in (confirm with context).')]
});
DP('st-candle-anatomy', {
  fu: [['Why can’t you know whether the high or the low came first?', 'A candle records only the four prices, not the path between them. The same OHLC could result from very different intra-period sequences. That is why single candles are read as summaries and confirmed by what follows, not as a play-by-play.'],
    ['What is a doji and why does it matter?', 'A doji has open ≈ close (a tiny or no body), showing balance between buyers and sellers. After a strong trend it can hint at exhaustion/indecision, but only in context and with confirmation — on its own it is just a pause.'],
    ['How does timeframe change a candle’s meaning?', 'The same shape carries more weight on a higher timeframe because it summarises more trading. A hammer on the weekly reflects a week-long rejection by many participants; the same shape on the 1-minute is minor noise.']],
  deep: [['Technique', 'Read three things on any candle: body size (conviction), wick length and side (rejection), and close location within the range (who finished in control) — then weigh by volume and location.'],
    ['Failure mode', 'Trading a single candle’s colour without context — e.g. buying a green candle that closed far off its high at resistance on low volume.'],
    ['In real charts', 'The highest-signal candles are large bodies closing near their extreme at a key level on strong volume; small-bodied long-wicked candles mark indecision and potential turns.']],
  src: ['StockCharts ChartSchool: Introduction to Candlesticks', 'https://chartschool.stockcharts.com/table-of-contents/chart-analysis/introduction-to-candlesticks'] });

STT('st-trend', { name: 'Trend & market structure', cat: 'stchart',
  blurb: `"The trend is your friend" is the oldest rule in trading because it works: trading with the prevailing direction puts probability on your side. Trend is defined precisely by market structure — the pattern of highs and lows — not by feel.`,
  facts: [['Uptrend', 'higher highs & higher lows'], ['Downtrend', 'lower highs & lower lows'], ['Range', 'sideways between levels'], ['Trade', 'with the trend, mostly']],
  cheat: [['Uptrend', 'Higher highs (HH) and higher lows (HL)'], ['Downtrend', 'Lower highs (LH) and lower lows (LL)'], ['Range / sideways', 'Roughly horizontal highs and lows'], ['Swing high', 'A peak with lower candles each side'], ['Swing low', 'A trough with higher candles each side'], ['Trend change', 'Structure breaks (e.g. a HL is broken in an uptrend)'], ['Pullback', 'A counter-move within a trend (your entry chance)'], ['Impulse vs correction', 'With-trend move vs against-trend pause'], ['Trend strength', 'Steepness, clean HHs/HLs, strong closes'], ['Rule', 'Favour trades in the trend’s direction']],
  sections: [
    ['The three market states', FIG2(
      FIG(chart({ w: 270, h: 190, candles: trend(20, 20, 0.25, 0.7, 3), notes: [{ i: 7, p: 22.2, text: 'HH', anchor: 'middle' }, { i: 11, p: 21.6, text: 'HL', anchor: 'middle' }] }), 'Uptrend: higher highs and higher lows.'),
      FIG(chart({ w: 270, h: 190, candles: trend(20, 26, -0.25, 0.7, 6), notes: [{ i: 7, p: 24.4, text: 'LH', anchor: 'middle' }, { i: 11, p: 24.8, text: 'LL', anchor: 'middle' }] }), 'Downtrend: lower highs and lower lows.')) +
      FIG(chart({ w: 560, h: 180, candles: trend(28, 30, 0, 1.3, 11), hlines: [{ p: 32.2, label: 'range top', cls: 'stc-res' }, { p: 27.8, label: 'range bottom', cls: 'stc-sup' }] }), 'Range: price oscillates sideways between support and resistance.')],
    ['Defining trend by structure', PP(`Forget "it looks like it’s going up." A trend is defined by <b>swing points</b>: an <b>uptrend</b> makes <b>higher highs and higher lows</b>; a <b>downtrend</b> makes <b>lower highs and lower lows</b>. As long as that pattern continues, the trend is intact. The trend is in question only when the structure <b>breaks</b> — for example, when an uptrend fails to make a new high and then breaks its last higher low.`)],
    ['Impulse and correction (why pullbacks are gifts)', PP(`Trends do not move in straight lines; they alternate <b>impulse</b> moves (with the trend) and <b>corrections/pullbacks</b> (against it). The pullback is where swing traders enter: you wait for the counter-move to pause at support (in an uptrend) and join the next impulse, getting a better price and a tighter stop than chasing the high. Buying pullbacks in an uptrend is the bread-and-butter swing trade.`)],
    ['Reading trend strength', UL([`<b>Clean structure:</b> clear, orderly HHs/HLs (or LHs/LLs) = a healthy trend.`, `<b>Steepness & closes:</b> strong candles closing near their highs show conviction.`, `<b>Shallow pullbacks</b> that hold above prior highs show strong demand; deep, sloppy pullbacks warn of weakening.`, `<b>Momentum fading</b> (smaller impulses, deeper corrections) often precedes a range or reversal — tighten up.`])]
  ],
  edge: [`Counter-trend trades (fighting the direction) are lower-probability — do them rarely and with tighter risk.`, `A single higher high does not make an uptrend; wait for structure (HH <i>and</i> HL) to confirm.`, `Trends end — a broken higher low in an uptrend is a warning, not a buy-the-dip signal.`, `In a range, trend-following whipsaws; recognise sideways conditions and either trade the edges or stand aside.`, `"The trend is your friend… until it bends" — don’t marry a direction after structure breaks.`],
  faq: [['How do I identify the trend objectively?', PP(`Mark the recent <b>swing highs and swing lows</b>. If each high is higher than the last and each low is higher than the last, it is an uptrend; the mirror is a downtrend; roughly flat is a range. This structural definition removes opinion — you are reading the actual sequence of peaks and troughs, not guessing.`)],
    ['Should I ever trade against the trend?', PP(`Mostly no, especially as a beginner — with-trend trades have probability on their side. Counter-trend trading (fading a move) is a real but <b>advanced, lower-probability</b> skill requiring tight stops and quick exits. Until you are consistent, trade pullbacks <i>in the direction of</i> the higher-timeframe trend.`)],
    ['When has a trend actually changed?', PP(`Not on the first pullback — on a <b>structure break</b>. In an uptrend, the warning is a failure to make a new higher high followed by a break below the most recent higher low; the mirror ends a downtrend. Even then, confirmation (a lower high forming, or a clear new opposite swing) reduces false signals. One red candle is not a trend change.`)]],
  qs: [SQ('What defines an uptrend?', ['Lots of green candles', 'A sequence of higher highs and higher lows', 'Price above a round number', 'High volume'], 1, 'Trend is defined by structure: higher highs and higher lows.'),
    SQ('Where do swing traders typically enter within a trend?', ['At the exact top', 'On a pullback that holds support, joining the next impulse', 'Randomly', 'Only on breakouts to new highs'], 1, 'Buying pullbacks in an uptrend gives a better price and tighter stop than chasing.')]
});
DP('st-trend', {
  fu: [['What is “break of structure” (BOS)?', 'When price violates the pattern that defined the trend — e.g. an uptrend breaking below its last higher low, or a downtrend breaking above its last lower high. It is the objective signal that the current trend is at risk or changing, used to exit or flip bias.'],
    ['How deep is a “normal” pullback?', 'Often a retracement into a prior support/resistance zone or a common Fibonacci area (38–62%). Shallow pullbacks signal strength; very deep ones (beyond ~62–78%) warn the trend may be failing. Depth is a clue, not a rule.'],
    ['How do you trade a range vs a trend?', 'In a trend, buy pullbacks (up) or sell rallies (down) with the direction. In a range, trade the edges — buy near support, sell near resistance — or wait for a breakout. Mixing them up (trend tactics in a range) causes whipsaw losses.']],
  deep: [['Technique', 'Mark swing highs/lows and label HH/HL or LH/LL. The structure tells you the trend, where it would break, and where pullback entries sit — all without indicators.'],
    ['Failure mode', 'Calling a trend from feel or a single big candle, or buying dips after structure has already broken ("catching a falling knife").'],
    ['In real charts', 'The strongest, most tradable trends show clean, orderly structure with shallow pullbacks; choppy overlapping candles mean a range where trend tactics fail.']],
  src: ['Investopedia: Trend Trading & Market Structure', 'https://www.investopedia.com/terms/t/trend.asp'] });

STT('st-sr', { name: 'Support & resistance', cat: 'stchart',
  blurb: `Support and resistance are the price levels where buyers and sellers have repeatedly turned the market. They are the single most useful map on a chart: where to expect reactions, where to place entries and stops, and where moves tend to begin and end.`,
  facts: [['Support', 'a floor where buyers step in'], ['Resistance', 'a ceiling where sellers step in'], ['Think', 'zones, not exact lines'], ['Role reversal', 'broken support → resistance']],
  cheat: [['Support', 'Price area where buying has repeatedly stopped falls'], ['Resistance', 'Price area where selling has repeatedly stopped rises'], ['Zone', 'A band, not a precise line — use the wick area'], ['Role reversal', 'Broken support becomes resistance (and vice versa)'], ['More touches', 'More tested = more significant (until it breaks)'], ['Round numbers', 'Psychological levels (e.g. 100, 1.2000)'], ['Prior swing highs/lows', 'Common S/R'], ['Breakout', 'Decisive close through a level on volume'], ['Retest', 'Price returns to the broken level — common entry'], ['Confluence', 'Several S/R reasons at one price = stronger']],
  sections: [
    ['Support, resistance and role reversal', FIG(chart({ w: 560, h: 250, candles: trend(34, 22, 0.08, 1.2, 15),
      hlines: [{ p: 24.6, label: 'resistance → becomes support', cls: 'stc-res' }, { p: 21.2, label: 'support', cls: 'stc-sup' }] }),
      'Price reacts at horizontal levels. When price finally breaks above resistance, that old ceiling often becomes new support on a pullback — "role reversal".')],
    ['How to find levels', OL([`Look for prices where the chart has <b>turned more than once</b> — repeated highs (resistance) or lows (support).`, `Mark <b>prior swing highs and lows</b>, and the edges of past ranges.`, `Note <b>round numbers</b> and psychologically important prices.`, `Draw <b>zones</b>, not hairlines: use the cluster of wicks/closes. Price is not a precise machine.`, `Favour levels on <b>higher timeframes</b> — weekly levels dominate daily ones.`])],
    ['Why levels work (and why they break)', PP(`Levels are <b>memory</b>: traders remember where they bought, sold, or wished they had, and act again near those prices. Buyers defend support; sellers defend resistance. But every level eventually breaks — when one side is exhausted. A decisive <b>close through</b> a level on strong volume signals a <b>breakout</b>; a weak poke that snaps back is a <b>false break</b>. The more times a level is tested without breaking, the more significant it is — but also the more orders pile up beyond it when it finally gives way.`)],
    ['Trading with levels: three uses', UL([`<b>Entries:</b> buy near support in an uptrend, sell near resistance in a downtrend; or enter on a <b>breakout/retest</b> of a level.`, `<b>Stops:</b> place stops just beyond a level — if support truly breaks, your trade idea is wrong, so you want out.`, `<b>Targets:</b> the next level up (for longs) or down (for shorts) is a logical take-profit — price often stalls there.`])]
  ],
  edge: [`Treating a level as an exact price leads to being stopped out by normal wick noise — use zones and give levels room.`, `Not every touch holds; a decisive close through a level on volume is a break, but a single wick through is often a false break (trap).`, `Placing a stop exactly at an obvious level invites a "stop hunt" poke — put it a little beyond the zone.`, `Old, far-away levels matter less than fresh, well-tested ones; don’t clutter the chart.`, `Levels are probabilities, not walls — combine with trend and confirmation, don’t trade a level blindly.`],
  faq: [['Line or zone — how exact should a level be?', PP(`Think in <b>zones</b>. Price is driven by countless orders, not a single number, so support and resistance are bands a few ticks/points wide (use the cluster of wicks and bodies). Drawing a hairline and expecting a reaction to the cent leads to being wicked out. A zone lets you place entries and stops with sensible room.`)],
    ['What is role reversal and why does it happen?', PP(`When price breaks <b>through</b> a level, the level often flips roles: broken resistance becomes support, and broken support becomes resistance. Psychologically, traders who sold at the old resistance now see price above it and buy the retest; breakout buyers add on the pullback. This <b>break-and-retest</b> is one of the most reliable entries in swing trading.`)],
    ['How do I know if a level will hold or break?', PP(`You do not know in advance — you trade probabilities. Clues: strong trends tend to break counter-trend levels and respect with-trend ones; approaching a level on <b>fading</b> momentum/volume favours a hold (reversal), while approaching on <b>strong</b> momentum favours a break. Wait for the candle’s <b>reaction</b> (a rejection wick to hold, a decisive close to break) rather than predicting.`)]],
  qs: [SQ('What typically happens to a resistance level after price decisively breaks above it?', ['It disappears', 'It often becomes support on a pullback (role reversal)', 'It becomes stronger resistance', 'Nothing'], 1, 'Broken resistance commonly flips to support — the basis of break-and-retest entries.'),
    SQ('Why should support and resistance be treated as zones rather than exact lines?', ['To make charts prettier', 'Because price is driven by many orders, so reactions occur in a band — exact lines get wicked out', 'Because exact lines are illegal', 'They should be exact lines'], 1, 'Zones reflect how real order flow behaves and avoid being stopped by minor wick noise.')]
});
DP('st-sr', {
  fu: [['What is a false breakout (fakeout) and how do you avoid being trapped?', 'Price pokes through a level then snaps back, trapping breakout traders. To avoid it, wait for a decisive close beyond the level (not just a wick), ideally on strong volume, or wait for the retest to hold before entering. False breaks themselves become trade signals (fade them back into the range).'],
    ['What is confluence?', 'When several independent reasons point to the same price — e.g. a prior swing low, a round number, a moving average, and a Fibonacci level all clustering. Confluence zones are stronger and higher-probability than a lone level.'],
    ['Do more touches make a level stronger or weaker?', 'More successful tests confirm a level matters — but each test also consumes the orders defending it, so a much-tested level can break decisively once that demand/supply is used up. Treat a many-times-tested level as significant but watch for exhaustion.']],
  deep: [['Technique', 'Mark major higher-timeframe levels first and trade reactions at them. The highest-probability entries cluster at confluence zones with a clear candle reaction (rejection or break-and-retest).'],
    ['Failure mode', 'Chasing a breakout the instant price touches the level (often a fakeout) or placing stops exactly on the obvious level where stop hunts occur.'],
    ['In real charts', 'Round numbers, prior swing extremes and the edges of long ranges are repeatedly defended; break-and-retest of a major level is among the most reliable swing setups.']],
  src: ['StockCharts ChartSchool: Support and Resistance', 'https://chartschool.stockcharts.com/table-of-contents/chart-analysis/support-and-resistance'] });

STT('st-trendlines', { name: 'Trendlines & channels', cat: 'stchart',
  blurb: `Trendlines turn the diagonal flow of a trend into a usable level: a line connecting the rising lows of an uptrend (or falling highs of a downtrend) shows where pullbacks have found support, and where a break would warn of change. Add a parallel line and you have a channel.`,
  facts: [['Uptrend line', 'connects rising lows'], ['Downtrend line', 'connects falling highs'], ['Needs', '2 points to draw, 3rd confirms'], ['Channel', 'two parallel lines']],
  cheat: [['Uptrend line', 'Connect two+ rising swing lows; support'], ['Downtrend line', 'Connect two+ falling swing highs; resistance'], ['Validity', '≥2 touches to draw, a 3rd confirms it matters'], ['Channel', 'Parallel line on the opposite side'], ['Ascending channel', 'Up-sloping; buy lower line, trim at upper'], ['Descending channel', 'Down-sloping; sell upper line'], ['Trendline break', 'Close through it warns of trend change'], ['Steepness', 'Very steep lines break easily (unsustainable)'], ['Don’t force it', 'If you have to cut through candles, it’s invalid'], ['Log scale', 'Often fits long trendlines better']],
  sections: [
    ['Drawing trendlines and channels', FIG2(
      FIG(chart({ w: 270, h: 200, candles: trend(22, 20, 0.2, 0.7, 3), tlines: [{ from: [1, 19.9], to: [20, 23.6], label: 'support' }] }), 'Uptrend line: connect the rising lows. Pullbacks to it are potential buys.'),
      FIG(chart({ w: 270, h: 200, candles: trend(22, 20, 0.2, 0.7, 3), tlines: [{ from: [1, 19.9], to: [20, 23.6] }, { from: [3, 21.4], to: [20, 25.2], dash: true }], notes: [{ i: 11, p: 25, text: 'channel', anchor: 'middle' }] }), 'Channel: add a parallel line across the highs. Trade between the rails.'))],
    ['How to draw them correctly', OL([`<b>Uptrend:</b> connect at least two <b>rising swing lows</b>. <b>Downtrend:</b> connect two <b>falling swing highs</b>.`, `You need <b>two points to draw</b> a line; a <b>third touch</b> that holds confirms it is real and tradable.`, `Connect the <b>extremes or the wick clusters</b> consistently; do not force a line through the middle of candles.`, `For a <b>channel</b>, draw a parallel line on the opposite side of the price action.`, `If a line only fits by ignoring obvious violations, it is not valid — the market is telling you the structure is different.`])],
    ['Trading trendlines and channels', UL([`<b>Pullback entries:</b> in an uptrend, buy when price pulls back <b>to the rising trendline</b> and shows a reaction (a rejection candle).`, `<b>Channel trading:</b> buy near the lower rail, consider trimming or taking profit near the upper rail (and the reverse in a down-channel).`, `<b>Stops:</b> just beyond the line/rail — a clean break means the setup failed.`, `<b>Trendline break:</b> a decisive close through a well-established trendline warns the trend may be pausing or reversing (confirm with structure).`])],
    ['Limits and judgement', PP(`Trendlines are partly subjective — two traders may draw them slightly differently, and you can often "fit" a line to tell any story. Guard against this by requiring <b>at least three touches</b>, drawing consistently, and treating the line as a <b>zone</b>. Very <b>steep</b> trendlines reflect unsustainable moves and break easily; shallower lines are more durable. Use trendlines alongside horizontal S/R and structure, not as a lone signal.`)]
  ],
  edge: [`Trendlines are subjective — you can draw one to fit any bias; require 3 touches and draw consistently.`, `Very steep lines break quickly (the move is unsustainable) — don’t trust near-vertical trendlines.`, `A wick poke through a trendline is not a break; wait for a decisive close beyond it.`, `Forcing a line through candle bodies to "make it work" produces fake signals — if it doesn’t fit cleanly, it isn’t valid.`, `Trendline breaks warn of change but aren’t automatic reversals; confirm with market structure and horizontal levels.`],
  faq: [['How many touches make a trendline valid?', PP(`Two points are enough to <b>draw</b> a line, but a <b>third touch that holds</b> is what confirms the market is actually respecting it. A line with three or more reactions is tradable; a two-point line is a hypothesis. More touches mean more significance — but, like horizontal levels, a much-tested line can eventually break.`)],
    ['Trendline or horizontal support — which is stronger?', PP(`Horizontal levels are generally more objective and widely watched than diagonal trendlines (everyone sees the same price; trendlines vary by drawing). Use trendlines to track the <i>slope</i> of a trend and time pullback entries, but give extra weight to horizontal S/R, and most of all to <b>confluence</b> where a trendline and a horizontal level meet.`)],
    ['What does a trendline break actually signal?', PP(`That the <i>rate</i> of the trend has changed — buyers (in an uptrend) no longer defend the rising line. It is an early <b>warning</b>, not a guaranteed reversal: price may simply slow into a shallower trend or a range. Confirm with market structure (a broken higher low) before flipping your bias; many trendline breaks just precede a pause.`)]],
  qs: [SQ('To draw a valid uptrend line, you connect…', ['Falling highs', 'Rising swing lows (2 to draw, a 3rd confirms)', 'Random points', 'The open of each candle'], 1, 'An uptrend line connects the rising lows that have acted as support.'),
    SQ('A near-vertical, very steep trendline is…', ['The most reliable kind', 'Likely unsustainable and prone to breaking quickly', 'Required for channels', 'A sign of low risk'], 1, 'Steep trendlines reflect parabolic, unsustainable moves and break easily.')]
});
DP('st-trendlines', {
  fu: [['What is a channel and how do you trade it?', 'Two parallel trendlines containing price. In an ascending channel you buy near the lower rail (with a reaction) and take profit/trim near the upper rail; the reverse in a descending channel. A decisive break of either rail signals the channel is ending.'],
    ['Why might a log scale matter for trendlines?', 'On assets that have moved a large percentage over time, a log scale (equal % = equal distance) keeps long trendlines meaningful; on a linear scale the same line curves away. For long-term weekly charts, log-scale trendlines often fit far better.'],
    ['How do you combine trendlines with horizontal levels?', 'Look for confluence: where a rising trendline meets a horizontal support, or a channel rail meets a round number. Those intersections are higher-probability reaction points than either alone.']],
  deep: [['Technique', 'Draw the trendline, then wait for price to return to it and print a reaction candle before entering — don’t anticipate the touch. Stops go just beyond the line; targets at the opposite rail or next horizontal level.'],
    ['Failure mode', 'Over-fitting lines to confirm a bias, trading a two-touch line as if confirmed, or reacting to wick pokes instead of closes.'],
    ['In real charts', 'The best trendline trades occur in clean channels with 3+ touches and at confluence with horizontal S/R; steep, lightly-touched lines are unreliable.']],
  src: ['StockCharts ChartSchool: Trend Lines', 'https://chartschool.stockcharts.com/table-of-contents/chart-analysis/trend-lines'] });
